    links: [{ label: "Homepage", url: "https://jenci.springeropen.com" }, { label: "NLM Catalog", url: "https://www.ncbi.nlm.nih.gov/nlmcatalog/9424566" }, { label: "DOAJ record", url: "https://doaj.org/toc/1110-0362" }],
